public async Task<IActionResult> Download(Guid id)
{
    var document = await _documents.FindAsync(id);
    var result = await _authorization.AuthorizeAsync(User, document, "SameAuthorPolicy");
    if (!result.Succeeded) return Forbid();          // enforcement at the operation
    return File(document.Content, "application/octet-stream");
}

